const sk1 = sketch('top'); sk1.rect(40,30,{at:[20,15]});
const e = extrude(sk1, -8);
hollow(e, { wall: 1, open: 'top' });

const sk1 = sketch('top'); sk1.rect(40,30,{at:[20,15]});
const e = extrude(sk1, -8);
hollow(e, { wall: 1, open: 'bottom' });

const sk1 = sketch('top'); sk1.rect(40,30,{at:[20,15]});
const e = extrude(sk1, 8);
hollow(e, { wall: 1, open: 'top' });

const sk1 = sketch('top'); sk1.rect(40,30,{at:[20,15]});
const e = extrude(sk1, -8);
round(e.edge('top','front'), 1);

const sk1 = sketch('top'); sk1.rect(40,30,{at:[20,15]});
const e = extrude(sk1, -8);
round(e.edge('bottom','front'), 1);

const sk1 = sketch('top'); sk1.rect(40,30,{at:[20,15]});
const e = extrude(sk1, -8);
draft(e.face('right'), 5);
